def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network referral rule: a self_employed applicant whose requested_limit
    # is above 6000 must go to manual review instead of being issued, no matter
    # what the partner decided. A decline stays a decline.
    if (
        app.get("employment") == "self_employed"
        and (app.get("requested_limit") or 0) > 6000
        and decision == "approve"
    ):
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}
    # decline (or anything else) stays a decline
    return {"action": "decline", "limit": 0}
